style.css:
@-moz-document domain("instagram.com") {
/* Stories bar */
  header div[role="presentation"] {
    background-color: rgba(0, 0, 0, 0.7) !important; /* dark frosted glass */
    backdrop-filter: blur(12px) saturate(120%) !important;
    border-radius: 12px !important;
    padding: 8px !important;
    transition: background 0.3s ease, backdrop-filter 0.3s ease;
  }

  /* Individual story hover effect */
  header div[role="presentation"] div {
    background: rgba(255, 255, 255, 0.05) !important;
    border-radius: 12px !important;
    transition: background 0.2s ease;
  }

  header div[role="presentation"] div:hover {
    background: rgba(255, 255, 255, 0.1) !important;
  }

  /* Feed wrapper - big dark plate */
  main > div[role="presentation"] {
    background-color: rgba(0, 0, 0, 0.85) !important; /* dark plate */
    backdrop-filter: blur(8px) saturate(120%) !important;
    border-radius: 12px !important;
    padding: 16px !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 0 !important; /* remove spacing between posts */
    max-width: 600px !important; /* keeps feed centered */
    margin: 0 auto !important;
  }

  /* Posts inside feed */
  main > div[role="presentation"] > article {
    background: transparent !important; /* posts natural */
    margin: 0 !important; /* remove gaps */
    box-shadow: none !important;
    border: none !important;
  }

  /* Remove all inner divisions inside posts */
  article, article * {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
  }

  /* Text readability */
  span, p, h1, h2, h3, h4, h5, h6, a {
    color: #fff !important;
  }
}
